import { FocusMonitor } from '@angular/cdk/a11y';
import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  forwardRef,
  HostBinding,
  HostListener,
  inject,
  Input,
  OnDestroy,
  Output,
  viewChild,
  ViewEncapsulation,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { ENTER, isPresent, voidFn } from '@questrade/allspark-angular-components/core/utils';
import { QSwitchIconComponent } from './switch-icon/switch-icon.component';

@Component({
  selector: 'q-switch',
  templateUrl: './switch.component.html',
  styleUrls: ['./switch.component.scss'],
  imports: [QSwitchIconComponent],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QSwitchComponent),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'q-switch',
    '[class.q-switch-checked]': 'checked',
    '[class.q-switch-disabled]': 'disabled',
    '(click)': 'onTouchTargetClick($event)',
  },
})
export class QSwitchComponent implements ControlValueAccessor, AfterViewInit, OnDestroy {
  @Output() readonly checkedChange = new EventEmitter<{ value: boolean; nativeEvent: Event }>();

  @Input({ transform: booleanAttribute }) @HostBinding('class.q-switch-checked') checked = false;
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-switch-disabled') disabled = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-switch';

  @HostListener('keydown', ['$event']) _onKeyDown(event: KeyboardEvent): void {
    if (event.code === ENTER && !this.disabled) {
      this._onInputInteraction(event);
    }
  }

  readonly inputElementRef = viewChild<ElementRef<HTMLInputElement>>('inputRef');

  private _onChange: (_: boolean) => void = voidFn;
  private _onTouch: () => void = voidFn;
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _elementRef = inject(ElementRef);

  ngAfterViewInit(): void {
    const inputElement = this.inputElementRef();

    if (inputElement) {
      this._focusMonitor.monitor(inputElement.nativeElement, true);
    }
  }

  ngOnDestroy(): void {
    this._focusMonitor.stopMonitoring(this._elementRef);
  }

  /** @hidden */
  writeValue(value: boolean): void {
    this.checked = isPresent<boolean>(value) && value;
    this._emitChangeEvent(new Event('change'));
  }

  /** @hidden */
  registerOnChange(fn: (_: boolean) => void): void {
    this._onChange = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouch = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
    this._changeDetectorRef.markForCheck();
  }

  protected onTouchTargetClick(event: Event): void {
    if (this.disabled) return;

    this.inputElementRef()?.nativeElement.focus();
    this._onInputInteraction(event);
  }

  protected onInputBlur(): void {
    this._onTouch();
  }

  private _onInputInteraction(event: Event): void {
    this.checked = !this.checked;
    this._emitChangeEvent(event);
  }

  private _emitChangeEvent(event: Event): void {
    this._onChange(this.checked);
    this.checkedChange.emit({
      value: this.checked,
      nativeEvent: event,
    });
    this._changeDetectorRef.markForCheck();
  }
}
