import {
  ChangeDetectionStrategy,
  Component,
  forwardRef,
  input,
  ViewEncapsulation,
} from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'q-switch-icon',
  templateUrl: './switch-icon.component.html',
  styleUrls: ['./switch-icon.component.scss'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QSwitchIconComponent),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'q-switch-icon',
    '[class.q-switch-icon-checked]': 'checked()',
    '[class.q-switch-icon-disabled]': 'disabled()',
  },
})
export class QSwitchIconComponent {
  checked = input.required<boolean>();
  disabled = input.required<boolean>();
}
